<?php require 'includes/functions.php';if(is_logged_in())go('index.php');if($_SERVER['REQUEST_METHOD']==='POST'){$login=trim($_POST['login']??'');$q=db()->prepare('SELECT * FROM users WHERE username=? OR email=? OR mobile=? LIMIT 1');$q->execute([$login,$login,$login]);$u=$q->fetch();if(!$u||!password_verify($_POST['password']??'',$u['password']))flash('danger','Invalid login credentials.');elseif($u['status']!=='active')flash('danger','Your account is blocked. Please contact the administrator.');else{$_SESSION['user']=['id'=>$u['id'],'username'=>$u['username'],'email'=>$u['email']];flash('success','Login successful.');go('index.php');}}$pageTitle='Login';require 'includes/header.php';require 'includes/navbar.php'; ?>
